BEGIN; CREATE VIRTUAL TABLE t3 USING fts3(c); CREATE TABLE result(docid INTEGER,o TEXT); INSERT INTO t3(rowid,c) VALUES(1,'Lorem ipsum dolor sit amet, consectetuer adipiscing elit. Maecenas iaculis mollis ipsum. Praesent rhoncus placerat justo. Duis non quam sed turpis posuere placerat. Curabitur et lorem in lorem porttitor aliquet. Pellentesque bibendum tincidunt diam. Vestibulum blandit ante nec elit. In sapien diam, facilisis eget, dictum sed, viverra at, felis. Vestibulum magna. Sed magna dolor, vestibulum rhoncus, ornare vel, vulputate sit amet, felis. Integer malesuada, tellus at luctus gravida, diam nunc porta nibh, nec imperdiet massa metus eu lectus. Aliquam nisi. Nunc fringilla nulla at lectus. Suspendisse potenti. Cum sociis natoque penatibus et magnis dis parturient montes, nascetur ridiculus mus. Pellentesque odio nulla, feugiat eu, suscipit nec, consequat quis, risus.'); INSERT INTO t3(rowid,c) VALUES(2,'Another lovely row'); WITH RECURSIVE n(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM n WHERE i<6000), d(txt) AS (SELECT group_concat((CASE WHEN i<=192 THEN 'l' ELSE 'x' END)||printf('%05d',i),' ') FROM n), r(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM r WHERE i<68) INSERT INTO t3(rowid,c) SELECT i+2,txt FROM r CROSS JOIN d; COMMIT;